@startuml

class Driver {
  + ID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + IsInRepairShop : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + ShiftType : ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class Schedule {
  + Date : date
}

class Assignment {
  + Date : date
}

Driver "1" -- "*" Assignment
Bus "1" -- "*" Assignment
Route "1" -- "*" Assignment
Shift "1" -- "*" Assignment

Assignment "1" -- "1" Schedule

@enduml

